 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before+IF(already_present=0,27,0) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before+IF(already_present=0,237,0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC105 unexpected table row-count delta'; END IF;
